@section('content')<div class="page-header"><div class="container-xl"><h2 class="page-title">Merit Generation · Version {{ $run->processing_version }}</h2></div></div><div class="page-body"><div class="container-xl"><div class="card"><div class="card-body"><div id="status" class="h3">{{ strtoupper($run->status) }}</div><div class="progress mb-3"><div id="bar" class="progress-bar" style="width:{{ $run->progress_percent }}%"></div></div><div id="counts" class="text-secondary">Processed {{ $run->processed_rows }} / {{ $run->total_rows }}</div><div id="failure" class="text-danger mt-2"></div></div></div></div></div><script>const url=@json(route('merit.run.status',$run));const poll=()=>fetch(url).then(r=>r.json()).then(d=>{document.getElementById('status').textContent=(d.status||'').toUpperCase();document.getElementById('bar').style.width=(d.progress_percent||0)+'%';document.getElementById('counts').textContent=`Processed ${d.processed_rows} / ${d.total_rows} · Common ${d.common_ranked_count} · General ${d.general_ranked_count} · Technical ${d.technical_ranked_count} · Cadre rows ${d.cadre_rank_rows}`;if(d.failure_message)document.getElementById('failure').textContent=d.failure_message;if(d.finished&&d.status==='completed'){location.href=@json(route('merit.results',['run'=>$run->id]));return;}if(!d.finished)setTimeout(poll,1000);});poll();</script>@endsection
